    "exp": "Los objetivos ATC incluyen prevenir colisiones entre aeronaves, prevenir colisiones entre aeronaves y obstáculos en el área de maniobras y acelerar/mantener un flujo ordenado. La respuesta marcada es literalmente el segundo objetivo; «área de movimientos» no es la expresión del manual y las clases A/F o solo VFR alteran el supuesto. Véase §1.2.1, p. 11.",
    "topic": "Cuadros azules de Fernando · Nº 106",
    "manualPage": 50,
    "manualName": "Tema 3 ATM · Cuadros azules de Fernando",
    "optionExp": [
      "CORRECTA — Prevenir colisiones entre aeronaves y obstáculos en el área de maniobras.: Es literalmente uno de los objetivos ATC: evitar colisiones entre aeronaves y obstáculos en el área de maniobras.",
      "NO — Acelerar, separar y mantener un flujo ordenado del tráfico aéreo IFR en espacio aéreo F.: No es el objetivo formulado: añade «IFR», «espacio F» y «separar» de manera incompatible con la enumeración general.",
      "NO — Prevenir colisiones entre aeronaves VFR en espacio aéreo A.: El manual no restringe ese objetivo a aeronaves VFR en clase A.",
      "NO — Prevenir colisiones entre aeronaves y obstáculos en el área de movimientos.: «Área de movimientos» no es la expresión del objetivo; el manual dice área de maniobras."
    ],
