    "deepExp": "Una autorización de aterrizaje incumplida durante cinco minutos, sin poder restablecer comunicación, es un supuesto expreso de fase de alerta. No es todavía la definición de incertidumbre ni, sin datos adicionales de peligro grave e inminente, la fase de socorro. Véase §1.4.3, p. 28.",
