    "q": "Cuando no se haya recibido ninguna comunicación de la aeronave dentro de los 30 minutos siguientes a la hora en que debía haberse recibido de ella una comunicación, o siguientes al momento en que por primera vez se trató infructuosamente de establecer comunicación con la misma, lo primero que suceda, se declara:",
