    "exp": "La AIP excluye de las medidas ATFM los vuelos en situación de emergencia, incluidos los secuestrados. No existe una exclusión general de todos los vuelos no comerciales, militares o de aviación general: la razón de la excepción es la emergencia y la prioridad de seguridad. Véase §1.7.5, p. 47, y la referencia AIP-España indicada en el banco.",
