      "CORRECTA — Aterrizar en el aeródromo apropiado más cercano y notificar la arribada a la dependencia de los servicios de tránsito aéreo. Es la actuación exigida en VMC: continuar visualmente, aterrizar en el aeródromo apropiado más cercano y notificar la llegada.",
