    "exp": "STCA significa Short Term Conflict Alert y está destinado a ayudar al controlador a prevenir colisiones entre aeronaves mediante una alerta de infracción potencial o real de mínimos de separación. La trampa es confundirlo con APM/APW o con TCAS, que es un sistema anticolisión de a bordo. Referencia: §9.2.1 y §9.2.B, pp. 258 y 262.",
